(()=>{'use strict';const C=window.FLIGHT_LIFECYCLE,el=id=>document.getElementById(id),key='flightdesk-sorties-v1',version=()=>window.FLIGHTDESK_BUILD?.appVersion||null,uid=()=>crypto.randomUUID();let state={version:1,sorties:[]},pending=null,blocked=false,lastDecision={status:'no-go',reasons:['Complete the pre-flight briefing']},selected='';
const card=document.createElement('section');card.id='flightcard';card.className='card';card.innerHTML=`<div class="cardhead"><h2>Flight · manual recording</h2><span id="flightphase" class="pill">No active flight</span></div><div class="body"><p><b>Manual flight timer and event log — no live aircraft telemetry.</b> Use before take-off and after landing, or ask ground crew to record events. No routine screen interaction is needed while flying. Follow aircraft warnings and your operating/emergency plan.</p><div class="flight-clock"><output id="flightelapsed">Not airborne</output><span id="flightremaining"></span></div><p id="flightcontext" class="hint"></p><p id="flightlivestatus" role="status"></p><div class="inline"><button id="recordtakeoff" class="btn primary" type="button">Record take-off</button><button id="recordlanding" class="btn primary" type="button" disabled>Record landing</button><button id="recordabort" class="btn" type="button" disabled>Log abort / return intention</button></div><p class="hint">Take-off records your explicit action and first saves the reviewed briefing. Complete Check for changes before this flight in Airspace before an assessed take-off. The timer uses timestamps, including time with the screen locked. It cannot detect take-off, landing or remaining charge.</p><details><summary>Quick event / note · optional</summary><label><span class="label">Event type</span><select id="flighteventtype"><option>Note</option><option>Conditions changed</option><option>Other aircraft observed</option><option>Battery alert</option><option>Loss of VLOS</option><option>Lost link</option><option>Return initiated</option><option>Emergency</option></select></label><label><span class="label">Observation / action taken · optional</span><textarea id="flighteventnote" maxlength="2000"></textarea></label><button id="recordevent" class="btn" type="button">Log event</button></details><details><summary>Record an already-airborne flight / unknown outcome</summary><p>Factual recovery only: this does not approve a launch or reconstruct missing checks. The record will be labelled UNASSESSED.</p><label><span class="label">Actual take-off · London date/time · required for recovery</span><input id="recoverytakeoff" type="datetime-local"></label><label><span class="label">Reason / time source · required for recovery or unknown outcome</span><textarea id="recoveryreason" maxlength="2000"></textarea></label><button id="recoverairborne" class="btn" type="button">Record already airborne · UNASSESSED</button><button id="unknownlanding" class="btn" type="button">Close active flight · landing/outcome unknown</button></details><details><summary>Cancel or postpone this plan · no flight recorded</summary><label><span class="label">Outcome</span><select id="canceloutcome"><option value="CANCELLED">Cancelled</option><option value="POSTPONED">Postponed</option></select></label><button id="cancelplan" class="btn" type="button">Record plan outcome</button></details><button id="recoverflightdownload" type="button" class="btn" hidden>Download unsaved flight-log recovery file</button><p id="flightlogstatus" class="hint" role="status"></p><details><summary>Flight events · recorded facts and corrections</summary><ol id="flightevents"></ol></details></div>`;
const post=document.createElement('section');post.id='postflightcard';post.className='card';post.innerHTML=`<div class="cardhead"><h2>Post-flight · debrief & records</h2></div><div class="body"><label><span class="label">Recorded sortie</span><select id="sortieselect"><option value="">No recorded sorties</option></select></label><p id="sortiesummary" class="hint"></p><div id="debriefeditor"><label><span class="label">Outcome · required to complete debrief</span><select id="debriefoutcome"><option value="">Select…</option><option value="completed">Completed</option><option value="partial">Partially completed</option><option value="aborted">Aborted</option><option value="cancelled">Cancelled</option><option value="postponed">Postponed</option><option value="unknown">Unknown</option></select></label><label><span class="label">Landing charge · lowest fitted pack · % · optional if unavailable</span><input id="landingcharge" type="number" min="0" max="100" step="any" placeholder="Leave blank if not recorded"></label><label><span class="label">Per-pack landing readings / temperatures · optional</span><textarea id="landingpacknotes" maxlength="2000" placeholder="Pack ID, charge, temperature and measurement source if available"></textarea></label><label class="check"><input id="debriefnothing" type="checkbox"><span>Nothing to report — defects, warnings and incidents considered</span></label><label class="check"><input id="debriefdefect" type="checkbox"><span>Defect / damage / safety concern — quarantine selected aircraft/battery for review</span></label><label><span class="label">Debrief / defect / lesson · required when reporting a defect; otherwise optional</span><textarea id="debriefnote" maxlength="3000"></textarea></label><label><span class="label">Follow-up / maintenance action · required for a defect; otherwise optional</span><textarea id="debrieffollowup" maxlength="2000"></textarea></label><label><span class="label">Deliverables / reference · optional</span><input id="debriefdeliverables" maxlength="1000"></label><button id="savedebrief" class="btn primary" type="button">Save debrief revision</button><p class="hint">Incomplete debriefs can be saved. Each save appends a revision; the original briefing and events remain. Defects carry forward until a documented return-to-service decision.</p><details><summary>Correct recorded times · retains previous values</summary><p>Leave a time blank to record it as unknown. Corrections are pilot-entered and are not independently authenticated.</p><label><span class="label">Corrected actual take-off · London time</span><input id="correcttakeoff" type="datetime-local"></label><label><span class="label">Corrected actual landing · London time</span><input id="correctlanding" type="datetime-local"></label><label><span class="label">Correction reason · required</span><textarea id="correctreason" maxlength="2000"></textarea></label><button id="correcttimes" class="btn" type="button">Append time correction</button></details><button id="downloadsorties" class="btn" type="button">Download flight/debrief report · HTML</button></div><p id="debriefstatus" class="hint" role="status"></p><div id="flighttotals" class="classhelp"></div><p class="hint">These are locally editable pilot records, not a certified or tamper-proof logbook. All-data JSON backups include these flight logs and revisions. Review private data before sharing reports.</p></div>`;
document.querySelector('.workspace').append(card,post);
function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function commit(next){if(pending)throw Error('An earlier flight-log update remains unsaved. Download its recovery file before reloading and importing it; no new log action was saved.');if(blocked)throw Error('Existing flight data needs recovery before further recording');try{C.validate(next);localStorage.setItem(key,JSON.stringify(next));state=next;pending=null;el('recoverflightdownload').hidden=true;el('flightlogstatus').textContent='Flight events saved in this browser · '+new Date().toISOString();window.dispatchEvent(new CustomEvent('flightdesk:flightlog'));render();return true;}catch(error){pending=next;el('recoverflightdownload').hidden=false;throw Error('Flight log NOT durably saved: '+error.message+'. Download the recovery file and retain it before continuing.');}}
function run(action,target='flightlogstatus'){try{action();}catch(error){el(target).textContent=error.message;}}
try{const raw=localStorage.getItem(key);if(raw)state=C.validate(JSON.parse(raw));selected=C.active(state)?.id||state.sorties.at(-1)?.id||'';}catch(error){blocked=true;el('flightlogstatus').textContent='Existing flight log could not be read. It has not been overwritten: download all-data backup before repair. '+error.message;}
function now(){return new Date().toISOString();}function local(value){return value?new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',dateStyle:'medium',timeStyle:'medium'}).format(new Date(value))+' Europe/London':'not recorded';}
function instant(value,optional=false){if(!value&&optional)return null;const time=window.FLIGHT_AIRSPACE.londonDateTime(value);if(time===null)throw Error('Enter an unambiguous London date/time; the daylight-saving transition time may be missing or repeated.');return new Date(time).toISOString();}
function current(){return state.sorties.find(r=>r.id===selected)||C.active(state)||null;}
function start(unassessed){if(pending)throw Error('An unsaved recovery log remains. Download it and reload/recover before another action.');if(C.active(state))throw Error('A flight is already active');window.updateFlightdeskDecision?.();const s=window.flightScopeReview?.(),o=window.flightOnsiteReview?.(),before=window.flightAirspaceBeforeFlight?.();if(!unassessed&&(!navigator.onLine||!['go','warning'].includes(lastDecision.status)||!s?.valid||!o?.valid||!before?.valid))throw Error('Assessed take-off blocked: complete the briefing, acceptable on-site conditions and Check for changes before this flight.');const brief=window.flightMissionAPI?.saveBriefing();if(!brief)throw Error('Enter project and mission title, then save the briefing before recording take-off');const id=uid(),time=now();if(!unassessed){const actual=Date.parse(time),duration=Number(brief.values.duration)*60000,times=brief.forecast?.hourly?.time||[],first=window.FLIGHT_AIRSPACE.londonDateTime(times[0]),last=window.FLIGHT_AIRSPACE.londonDateTime(times.at(-1)),air=brief.airspace;if(!Number.isFinite(first)||!Number.isFinite(last)||actual<first||actual+duration>last||actual<Date.parse(air?.searchWindowStart)||actual+duration>Date.parse(air?.searchWindowEnd))throw Error('The actual take-off interval is outside reviewed forecast/airspace coverage. Update estimated take-off time and repeat the affected reviews.');}const next=C.start(state,{id,now:time,takeoffAt:unassessed?instant(el('recoverytakeoff').value):time,briefing:brief,readiness:lastDecision,onsite:o,scope:s,beforeFlight:before,unassessed,notes:unassessed?el('recoveryreason').value:'',version:version()});commit(next);selected=id;window.flightAirspaceBeginSortie?.();fillDebrief();render();}
el('recordtakeoff').onclick=()=>run(()=>start(false));el('recoverairborne').onclick=()=>run(()=>start(true));
function add(type,notes=''){const r=C.active(state);if(!r)throw Error('No active flight');const time=now();commit(C.event(state,r.id,{eventId:uid(),type,now:time,notes,version:version()}));selected=r.id;if(type==='landing'||type==='outcome-unknown'){fillDebrief();render();window.updateFlightdeskDecision?.();}}
el('recordlanding').onclick=()=>run(()=>add('landing'));el('recordabort').onclick=()=>run(()=>add('abort','Pilot recorded abort/return intention; aircraft landing not yet confirmed.'));el('unknownlanding').onclick=()=>run(()=>add('outcome-unknown',el('recoveryreason').value));el('recordevent').onclick=()=>run(()=>{add(el('flighteventtype').value,el('flighteventnote').value);el('flighteventnote').value='';});
el('recoverflightdownload').onclick=()=>download('flightdesk-unsaved-flight-log.json',JSON.stringify({format:'flightdesk-flight-log-recovery',...pending},null,2));
el('cancelplan').onclick=()=>run(()=>{if(C.active(state))throw Error('An airborne flight cannot be cancelled as though it never flew');const brief=window.flightMissionAPI?.saveBriefing();if(!brief)throw Error('Enter project and mission titles first');const time=now(),id=uid(),outcome=el('canceloutcome').value;const r={id,createdAt:time,phase:outcome,missionId:brief.missionId,projectTitle:brief.projectTitle,missionTitle:brief.missionTitle,briefingId:brief.id,briefing:brief,assessment:'NOT_FLOWN',takeoffAt:null,landingAt:null,events:[{id:uid(),type:outcome.toLowerCase(),recordedAt:time,occurredAt:time,appVersion:version()}],debriefs:[],appVersion:version()};commit({...state,sorties:[...state.sorties,r]});selected=id;render();});
function fillDebrief(){const r=current(),d=r?.debriefs.at(-1);el('debriefoutcome').value=d?.outcome||(['CANCELLED','POSTPONED'].includes(r?.phase)?r.phase.toLowerCase():'');for(const[id,k]of [['landingcharge','landingCharge'],['landingpacknotes','packNotes'],['debriefnote','note'],['debrieffollowup','followup'],['debriefdeliverables','deliverables']])el(id).value=d?.[k]??'';el('debriefnothing').checked=!!d?.nothingToReport;el('debriefdefect').checked=!!d?.defect;}
el('sortieselect').onchange=()=>{selected=el('sortieselect').value;fillDebrief();render();};el('debriefnothing').onchange=()=>{if(el('debriefnothing').checked)el('debriefdefect').checked=false;};el('debriefdefect').onchange=()=>{if(el('debriefdefect').checked)el('debriefnothing').checked=false;};
el('savedebrief').onclick=()=>run(()=>{const r=current();if(!r)throw Error('Select a recorded flight');const next=C.debrief(state,r.id,{recordedAt:now(),appVersion:version(),outcome:el('debriefoutcome').value,landingCharge:el('landingcharge').value===''?null:Number(el('landingcharge').value),packNotes:el('landingpacknotes').value,nothingToReport:el('debriefnothing').checked,defect:el('debriefdefect').checked,note:el('debriefnote').value,followup:el('debrieffollowup').value,deliverables:el('debriefdeliverables').value});commit(next);if(el('debriefdefect').checked){window.flightAssetQuarantine?.(r.briefing,el('debriefnote').value);}el('debriefstatus').textContent='Debrief revision saved. '+(current()?.debriefs.at(-1)?.complete?'Debrief complete.':'Some closing information remains unrecorded.');},'debriefstatus');
el('correcttimes').onclick=()=>run(()=>{const r=current();if(!r)throw Error('Select a recorded flight');commit(C.correct(state,r.id,{takeoffAt:instant(el('correcttakeoff').value,true),landingAt:instant(el('correctlanding').value,true),reason:el('correctreason').value,now:now(),eventId:uid(),version:version()}));el('debriefstatus').textContent='Time correction appended; previous values retained in event history.';},'debriefstatus');
function escape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
el('downloadsorties').onclick=()=>download('flightdesk-flight-debrief-records.html','<!doctype html><html lang="en"><meta charset="utf-8"><title>Flightdesk flight/debrief records</title><style>body{font:16px system-ui;max-width:1000px;margin:30px auto;padding:20px}pre{white-space:pre-wrap;overflow-wrap:anywhere}article{break-before:page}</style><h1>Flightdesk UK · flight and debrief records</h1><p>Pilot-entered records, not independent compliance verification or a tamper-proof logbook. Exported '+escape(now())+'; app '+escape(version())+'. Times stored in UTC; no aircraft telemetry.</p>'+state.sorties.map(r=>'<article><h2>'+escape(r.projectTitle)+' / '+escape(r.missionTitle)+'</h2><p>'+escape(r.phase)+' · '+escape(r.assessment)+' · actual elapsed '+escape(C.elapsed(r)===null?'not recorded':C.elapsed(r).toFixed(1)+' min')+'</p><pre>'+escape(JSON.stringify(r,null,2))+'</pre></article>').join(''),'text/html');
function timer(){const r=C.active(state),timeUncertain=!!r&&(Date.now()<Date.parse(r.takeoffAt)||C.elapsed(r)>180);banner.hidden=!r;banner.textContent=r?'AIRBORNE · '+r.assessment+' recorded at launch. The readiness cards below concern a future take-off; they do not rewrite this flight. Use Flight to record landing.':'';el('flightelapsed').textContent=r?(C.elapsed(r)===null?'Time unknown':C.elapsed(r).toFixed(1)+' min elapsed'):'Not airborne';const allowance=Number(r?.briefing?.values?.duration);el('flightremaining').textContent=r&&allowance>0?'Estimated allowance remaining: '+Math.max(0,allowance-C.elapsed(r)).toFixed(1)+' min · estimate only':'';el('flightlivestatus').textContent=r?'Airborne — '+(!navigator.onLine?'offline; live services unavailable. ':'')+'Reassess conditions / follow your operating and emergency plan.'+(timeUncertain?' Clock/time concern: elapsed time is outside the supported planning range; verify actual times and record a correction when appropriate.':''): 'No flight is recorded airborne. Pre-flight readiness is separate from recorded outcomes.';}
function render(){const r=current(),active=C.active(state);el('flightphase').textContent=active?'AIRBORNE · '+active.assessment:'No active flight';el('recordtakeoff').disabled=!!active||blocked||!['go','warning'].includes(lastDecision.status)||!window.flightAirspaceBeforeFlight?.().valid;for(const id of ['recordlanding','recordabort'])el(id).disabled=!active||blocked;el('flightcontext').textContent=active?[active.projectTitle,active.missionTitle,'Aircraft: '+(active.briefing?.values?.aircraft||'not recorded'),'Pilot: '+(active.briefing?.pilot?.name||'not recorded'),'Battery: '+(active.briefing?.battery?.name||'not recorded'),'Landing reserve: '+(active.briefing?.values?.reserve||'not recorded')+'%'].join(' · '):'';
const select=el('sortieselect');if(select.options.length!==state.sorties.length||Array.from(select.options).some((o,i)=>o.value!==state.sorties[i]?.id)){select.replaceChildren();for(const item of state.sorties){const option=document.createElement('option');option.value=item.id;option.textContent=item.projectTitle+' / '+item.missionTitle+' · '+item.phase+' · '+local(item.createdAt);select.append(option);}}for(const option of select.options){const item=state.sorties.find(s=>s.id===option.value);if(item)option.textContent=item.projectTitle+' / '+item.missionTitle+' · '+item.phase+' · '+local(item.createdAt);}for(const [id,complete]of [['flightcard',!!r&&r.phase!=='AIRBORNE'],['postflightcard',r?.phase==='DEBRIEF_COMPLETE']]){const d=el(id).querySelector('.field-section');if(d){d.classList.toggle('section-complete',complete);d.classList.toggle('section-attention',!!r&&!complete);d.classList.toggle('section-warning',id==='flightcard'&&!!active);}}select.value=r?.id||'';el('sortiesummary').textContent=r?r.phase+' · '+r.assessment+' · Take-off '+local(r.takeoffAt)+' · Landing '+local(r.landingAt)+' · Actual duration '+(C.elapsed(r)===null?'not recorded':C.elapsed(r).toFixed(1)+' min')+(r.clockUncertain?' · Time uncertainty/correction recorded':''): 'No flight has been recorded. Saving a briefing alone does not record a flight.';el('savedebrief').disabled=!r||r.phase==='AIRBORNE';el('flightevents').replaceChildren();for(const event of (active||r)?.events||[]){const li=document.createElement('li');li.textContent=local(event.occurredAt)+' · '+event.type+(event.notes?' · '+event.notes:'');el('flightevents').append(li);}const flown=state.sorties.filter(s=>s.takeoffAt),known=flown.map(s=>C.elapsed(s)).filter(Number.isFinite);el('flighttotals').textContent=flown.length+' sortie(s) with recorded take-off · '+known.reduce((a,b)=>a+b,0).toFixed(1)+' min recorded elapsed · '+flown.filter(s=>!s.landingAt).length+' without recorded landing. No flight counts are converted into full battery cycles.';timer();}
const banner=document.createElement('p');banner.className='phase-banner';banner.hidden=true;el('decisioncard').before(banner);
const recoveryInput=document.createElement('input');recoveryInput.type='file';recoveryInput.accept='.json,application/json';recoveryInput.hidden=true;card.querySelector('.body').append(recoveryInput);const recoveryButton=document.createElement('button');recoveryButton.type='button';recoveryButton.className='btn';recoveryButton.textContent='Import flight-log recovery file';el('recoverflightdownload').after(recoveryButton);recoveryButton.onclick=()=>recoveryInput.click();recoveryInput.onchange=async()=>{try{const file=recoveryInput.files?.[0];if(!file)return;if(file.size>50*1024*1024)throw Error('Recovery file exceeds 50 MB');const data=window.FLIGHTDESK_BACKUP.parse(await file.text());if(data.format!=='flightdesk-flight-log-recovery')throw Error('Use a Flightdesk flight-log recovery file; use Upload past flight records for all-data backups');const merged=window.FLIGHTDESK_BACKUP.mergeSettings({[key]:JSON.stringify(state)},{[key]:JSON.stringify(C.validate({version:data.version,sorties:data.sorties}))},C.validate);commit(JSON.parse(merged[key]));selected=C.active(state)?.id||state.sorties.at(-1)?.id||'';fillDebrief();render();}catch(error){el('flightlogstatus').textContent='Recovery file not imported: '+error.message;}finally{recoveryInput.value='';}};
window.flightActiveSortie=()=>C.active(state);window.flightHasActive=()=>!!C.active(state);window.addEventListener('flightdesk:restored',()=>{try{state=C.validate(JSON.parse(localStorage.getItem(key)||'{"version":1,"sorties":[]}'));selected=C.active(state)?.id||state.sorties.at(-1)?.id||'';blocked=false;fillDebrief();render();}catch(error){blocked=true;el('flightlogstatus').textContent='Restored flight log requires recovery: '+error.message;}});window.flightLifecycleSnapshot=()=>JSON.parse(JSON.stringify(state));window.addEventListener('flightdesk:decision',e=>{lastDecision=e.detail;render();});window.addEventListener('online',timer);window.addEventListener('offline',timer);document.addEventListener('visibilitychange',timer);setInterval(timer,1000);fillDebrief();render();
})();
